import{_ as r,o as t,c as a,a3 as i}from"./chunks/framework.BrO6lPIi.js";const d=JSON.parse('{"title":"文件操作服务","description":"本文件操作服务由 Chrome 扩展端与独立 Agent 进程组成。","frontmatter":{"title":"文件操作服务","description":"本文件操作服务由 Chrome 扩展端与独立 Agent 进程组成。"},"headers":[],"relativePath":"本地代理服务/文件操作服务/index.md","filePath":"本地代理服务/文件操作服务/index.md","lastUpdated":null}'),s={name:"本地代理服务/文件操作服务/index.md"};function o(n,e,l,c,g,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="文件操作服务" tabindex="-1">文件操作服务 <a class="header-anchor" href="#文件操作服务" aria-label="Permalink to &quot;文件操作服务&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js" target="_blank" rel="noreferrer">agent/src/trash.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/integration/api.integration.test.js" target="_blank" rel="noreferrer">agent/test/integration/api.integration.test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源限制">性能与资源限制</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#安全最佳实践">安全最佳实践</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件操作服务由 Chrome 扩展端与独立 Agent 进程组成。扩展端通过本地 HTTP/WebSocket 调用 Agent 提供的文件系统接口，实现路径受限的文件读取、写入、列表、统计、重命名、移动、删除、上传、下载、预览和回收站恢复等操作。Agent 侧的安全机制以“白名单 + 硬阻止 + 符号链接校验”为核心，回收站提供软删除、跨设备迁移、过期清理和元数据持久化；批量下载通过 ZIP 打包，流式上传/下载避免大文件内存膨胀。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>与文件操作直接相关的代码主要分布在以下位置：</p><ul><li>Agent HTTP 路由与文件操作实现：<code>agent/src/server.js</code></li><li>路径白名单、符号链接防护、命令分级安全策略：<code>agent/src/security.js</code></li><li>回收站模块（移动、恢复、清理、定时任务）：<code>agent/src/trash.js</code></li><li>扩展端侧边栏文件操作封装：<code>src/side_panel/workspace-manager.js</code></li><li>文件系统 API 集成测试：<code>agent/test/integration/api.integration.test.js</code></li></ul><pre class="mermaid">graph TB
Client[&quot;Chrome 扩展&lt;br/&gt;side_panel&quot;] --&gt; Server[&quot;Agent HTTP 服务器&lt;br/&gt;server.js&quot;]
Server --&gt; Security[&quot;路径与安全检查&lt;br/&gt;security.js&quot;]
Server --&gt; Trash[&quot;回收站模块&lt;br/&gt;trash.js&quot;]
Server --&gt; FS[&quot;Node 文件系统&lt;br/&gt;fs / fs/promises&quot;]
Server --&gt; Logger[&quot;日志记录&lt;br/&gt;logger.js&quot;]
Server --&gt; Search[&quot;搜索工具&lt;br/&gt;search.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L20" target="_blank" rel="noreferrer">agent/src/server.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L443" target="_blank" rel="noreferrer">agent/src/server.js#L417-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L1-L10" target="_blank" rel="noreferrer">agent/src/trash.js#L1-L10</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L60" target="_blank" rel="noreferrer">agent/src/server.js#L1-L60</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L30" target="_blank" rel="noreferrer">agent/src/security.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L1-L40" target="_blank" rel="noreferrer">agent/src/trash.js#L1-L40</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L569-L616" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L569-L616</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li><strong>HTTP 路由层</strong>：统一处理认证、国际化、CORS、请求体解析、文件大小限制、日志记录和错误响应。</li><li><strong>路径安全检查层</strong>：负责路径格式规整、工作目录放行、白名单前缀匹配、符号链接 <code>realpath</code> 校验、敏感路径硬阻止。</li><li><strong>回收站模块</strong>：负责将删除目标移动到 <code>.ai-helper-agent/.trash</code>，记录元数据，支持恢复、过期清理和跨设备回退复制。</li><li><strong>文件操作端点</strong>：提供 <code>/api/fs/read|write|list|stat|mkdir|rename|move|delete|upload-stream|download*|preview-xlsx</code> 等能力。</li><li><strong>扩展端封装</strong>：提供 <code>deleteFs</code>、<code>renameFs</code>、<code>createDir</code>、<code>moveFs</code>、<code>getFileInfo</code> 等调用入口。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L443" target="_blank" rel="noreferrer">agent/src/server.js#L417-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L862" target="_blank" rel="noreferrer">agent/src/server.js#L751-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1037-L1559" target="_blank" rel="noreferrer">agent/src/server.js#L1037-L1559</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L102-L229" target="_blank" rel="noreferrer">agent/src/security.js#L102-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L160-L251" target="_blank" rel="noreferrer">agent/src/trash.js#L160-L251</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L569-L616" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L569-L616</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>文件操作请求的典型流程如下：</p><pre class="mermaid">sequenceDiagram
participant UI as &quot;扩展端界面&quot;
participant WM as &quot;workspace-manager.js&quot;
participant S as &quot;server.js&quot;
participant SEC as &quot;security.js&quot;
participant TR as &quot;trash.js&quot;
participant FS as &quot;Node 文件系统&quot;
UI-&gt;&gt;WM : 调用 deleteFs(path)
WM-&gt;&gt;S : POST /api/fs/delete { path }
S-&gt;&gt;SEC : checkPath(path)
SEC--&gt;&gt;S : allowed/resolved/reason
alt 允许访问
S-&gt;&gt;FS : stat(path)
FS--&gt;&gt;S : 文件信息
S-&gt;&gt;TR : moveToTrash(resolved)
TR-&gt;&gt;FS : rename/cp/rm
TR--&gt;&gt;S : trashId/isDir
S--&gt;&gt;WM : success + trashId
else 拒绝访问
S--&gt;&gt;WM : 403 + reason
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L569-L583" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L569-L583</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1145-L1161" target="_blank" rel="noreferrer">agent/src/server.js#L1145-L1161</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L166-L202" target="_blank" rel="noreferrer">agent/src/trash.js#L166-L202</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="路径白名单验证与目录遍历防护" tabindex="-1">路径白名单验证与目录遍历防护 <a class="header-anchor" href="#路径白名单验证与目录遍历防护" aria-label="Permalink to &quot;路径白名单验证与目录遍历防护&quot;">​</a></h3><p>路径检查的核心逻辑位于 <code>checkPath</code>：</p><ul><li>输入为空或非字符串时直接拒绝。</li><li>展开 <code>~</code> 到用户主目录。</li><li>使用 <code>normalizePathFormat</code> 处理 Windows 盘符、MSYS 路径、反斜杠和大写盘符。</li><li>先做绝对路径解析与工作目录合并。</li><li>执行硬阻止检查，禁止访问 Agent 配置、配对记录、MCP 配置、日志、回收站、技能状态等敏感路径。</li><li>对记忆存储目录和工作目录做特殊放行。</li><li>对 <code>allowedPaths</code> 做前缀匹配。</li><li>使用 <code>realpath</code> 解析符号链接，并对真实路径再次执行硬阻止和前缀检查。</li><li>最终返回 <code>allowed</code>、<code>resolved</code> 或拒绝原因。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;进入 checkPath&quot;]) --&gt; ValidateInput[&quot;校验 path 是否为非空字符串&quot;]
ValidateInput --&gt; ExpandTilde[&quot;展开 ~ 到用户主目录&quot;]
ExpandTilde --&gt; Normalize[&quot;normalizePathFormat 规整路径&quot;]
Normalize --&gt; Resolve[&quot;resolve + normalize 得到规范化路径&quot;]
Resolve --&gt; HardBlock[&quot;硬阻止检查&quot;]
HardBlock --&gt; MemoryWorkdir{&quot;是否命中记忆目录或工作目录？&quot;}
MemoryWorkdir --&gt; |是| RealpathCheck[&quot;realpath 解析符号链接&quot;]
MemoryWorkdir --&gt; |否| AllowedPrefix[&quot;allowedPaths 前缀匹配&quot;]
AllowedPrefix --&gt; RealpathCheck
RealpathCheck --&gt; HardBlockReal[&quot;对 realPath 再次硬阻止&quot;]
HardBlockReal --&gt; AllowedPrefixReal[&quot;对 realPath 再次前缀匹配&quot;]
AllowedPrefixReal --&gt; Result[&quot;返回 allowed/resolved/reason&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L40-L60" target="_blank" rel="noreferrer">agent/src/security.js#L40-L60</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L100" target="_blank" rel="noreferrer">agent/src/security.js#L62-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L40-L60" target="_blank" rel="noreferrer">agent/src/security.js#L40-L60</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L100" target="_blank" rel="noreferrer">agent/src/security.js#L62-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h3 id="符号链接检测与权限控制" tabindex="-1">符号链接检测与权限控制 <a class="header-anchor" href="#符号链接检测与权限控制" aria-label="Permalink to &quot;符号链接检测与权限控制&quot;">​</a></h3><ul><li>符号链接绕过防护：所有可访问路径都经过 <code>realpath</code> 解析，确保实际落盘位置仍在白名单内且未命中硬阻止清单。</li><li>工作目录永远放行，但会通过 <code>realpath</code> 防止通过工作目录内的符号链接逃逸到 Agent 系统目录。</li><li>脚本文件写入后强制剥离执行权限：当文件扩展名为常见脚本类型或内容包含 shebang 时，设置权限为 <code>0o644</code>，降低直接执行风险。</li><li>流式上传的脚本文件同样会执行权限剥离。</li><li>文件统计接口返回 <code>mode</code>、<code>uid</code>、<code>gid</code>、<code>isSymbolicLink</code> 等元信息，便于上层判断文件属性。</li></ul><pre class="mermaid">classDiagram
class Security {
+checkPath(path, tFn)
+checkCommand(command, force, tFn)
+normalizePathFormat(pathStr, platformOverride)
+isHardBlocked(normalizedPath, platformOverride)
}
class Server {
+handleRequest(req, res)
+parseBody(req)
+parseMultipartBody(req)
+getMimeType(filePath)
}
class Trash {
+moveToTrash(sourcePath, tFn)
+restoreFromTrash(trashId, tFn)
+listTrash()
+startPeriodicCleanup()
+stopPeriodicCleanup()
}
Server --&gt; Security : &quot;路径安全检查&quot;
Server --&gt; Trash : &quot;删除转回收站&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L760-L761" target="_blank" rel="noreferrer">agent/src/security.js#L760-L761</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1052-L1087" target="_blank" rel="noreferrer">agent/src/server.js#L1052-L1087</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L849-L853" target="_blank" rel="noreferrer">agent/src/server.js#L849-L853</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1113-L1142" target="_blank" rel="noreferrer">agent/src/server.js#L1113-L1142</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L166-L202" target="_blank" rel="noreferrer">agent/src/trash.js#L166-L202</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L148-L160" target="_blank" rel="noreferrer">agent/src/security.js#L148-L160</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L180-L229" target="_blank" rel="noreferrer">agent/src/security.js#L180-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1075-L1083" target="_blank" rel="noreferrer">agent/src/server.js#L1075-L1083</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L849-L853" target="_blank" rel="noreferrer">agent/src/server.js#L849-L853</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1113-L1142" target="_blank" rel="noreferrer">agent/src/server.js#L1113-L1142</a></li></ul><h3 id="文件读写与编码转换" tabindex="-1">文件读写与编码转换 <a class="header-anchor" href="#文件读写与编码转换" aria-label="Permalink to &quot;文件读写与编码转换&quot;">​</a></h3><ul><li><strong>文本读取</strong>：<code>/api/fs/read</code> 要求路径允许、存在且不是目录，按 <code>utf-8</code> 读取并返回 content、size、path。</li><li><strong>文本写入</strong>：<code>/api/fs/write</code> 支持 <code>utf-8</code> 和 <code>base64</code> 两种编码；<code>base64</code> 会解码为 Buffer 再写入，用于二进制文件。</li><li><strong>二进制文件支持</strong>：通过 <code>encoding: &#39;base64&#39;</code> 写入二进制内容；<code>/api/fs/download</code> 返回 base64 内容和 MIME 类型。</li><li><strong>流式上传</strong>：<code>/api/fs/upload-stream</code> 接收原始二进制 body，按 <code>Content-Length</code> 和累计字节数双重限制，写入完成后剥离脚本执行权限。</li><li><strong>流式下载</strong>：<code>/api/fs/download-stream</code> 单文件使用 <code>createReadStream</code> 直接管道输出，避免整个文件加载到内存；目录则先打包为 ZIP 再分块发送。</li><li><strong>MIME 类型推断</strong>：根据扩展名映射常见文本、图片、音视频、Office、压缩包类型。</li></ul><pre class="mermaid">flowchart TD
ReadReq[&quot;POST /api/fs/read&quot;] --&gt; CheckPath[&quot;checkPath 校验&quot;]
CheckPath --&gt; Exists[&quot;检查是否存在&quot;]
Exists --&gt; IsFile{&quot;是否文件？&quot;}
IsFile --&gt; |否| ErrorDir[&quot;返回 400 路径是目录&quot;]
IsFile --&gt; |是| SizeCheck[&quot;检查大小限制&quot;]
SizeCheck --&gt; ReadUtf8[&quot;utf-8 读取&quot;]
ReadUtf8 --&gt; ReadResp[&quot;返回 content/size/path&quot;]
WriteReq[&quot;POST /api/fs/write&quot;] --&gt; CheckPathW[&quot;checkPath 校验&quot;]
CheckPathW --&gt; Encoding{&quot;encoding 是 base64？&quot;}
Encoding --&gt; |是| DecodeBase64[&quot;Buffer.from(base64)&quot;]
Encoding --&gt; |否| Utf8Buf[&quot;Buffer.from(utf-8)&quot;]
DecodeBase64 --&gt; WriteBinary[&quot;writeFile(Buffer)&quot;]
Utf8Buf --&gt; WriteText[&quot;writeFile(text)&quot;]
WriteBinary --&gt; ScriptChmod[&quot;脚本文件 chmod 0o644&quot;]
WriteText --&gt; ScriptChmod
ScriptChmod --&gt; WriteResp[&quot;返回 size/path&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1037-L1050" target="_blank" rel="noreferrer">agent/src/server.js#L1037-L1050</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1052-L1087" target="_blank" rel="noreferrer">agent/src/server.js#L1052-L1087</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L196-L220" target="_blank" rel="noreferrer">agent/src/server.js#L196-L220</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1037-L1050" target="_blank" rel="noreferrer">agent/src/server.js#L1037-L1050</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1052-L1087" target="_blank" rel="noreferrer">agent/src/server.js#L1052-L1087</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L196-L220" target="_blank" rel="noreferrer">agent/src/server.js#L196-L220</a></li></ul><h3 id="批量操作与原子性保证" tabindex="-1">批量操作与原子性保证 <a class="header-anchor" href="#批量操作与原子性保证" aria-label="Permalink to &quot;批量操作与原子性保证&quot;">​</a></h3><ul><li><strong>重命名</strong>：<code>/api/fs/rename</code> 仅修改文件名，不跨目录；校验新名称不含路径分隔符，Windows 下过滤非法字符；目标已存在返回 409；目标路径也经过 <code>checkPath</code> 校验。</li><li><strong>移动</strong>：<code>/api/fs/move</code> 要求源存在、目标目录存在；计算目标完整路径后再次校验；目标已存在返回 409；底层使用 <code>rename</code>。</li><li><strong>删除</strong>：<code>/api/fs/delete</code> 不直接物理删除，而是调用 <code>moveToTrash</code>，返回 <code>trashId</code>。</li><li><strong>原子性与事务回滚</strong>：当前实现没有显式的事务管理器或回滚机制。重命名和移动依赖文件系统原语；删除依赖回收站模块。若中间步骤失败，可能产生部分状态，例如回收站元数据写入前文件已移动，或移动失败时清理半成品目标。文档应明确：<strong>该服务不承诺跨多个操作的 ACID 事务</strong>。</li></ul><pre class="mermaid">flowchart TD
RenameReq[&quot;POST /api/fs/rename&quot;] --&gt; ValidateName[&quot;校验 newName 无分隔符/非法字符&quot;]
ValidateName --&gt; CheckOld[&quot;checkPath(oldPath)&quot;]
CheckOld --&gt; ExistsOld[&quot;检查旧路径存在&quot;]
ExistsOld --&gt; NewFullPath[&quot;拼接新路径&quot;]
NewFullPath --&gt; CheckNew[&quot;checkPath(newFullPath)&quot;]
CheckNew --&gt; ExistsNew{&quot;目标已存在？&quot;}
ExistsNew --&gt; |是| Conflict409[&quot;返回 409 冲突&quot;]
ExistsNew --&gt; |否| DoRename[&quot;rename(old, new)&quot;]
DoRename --&gt; RenameResp[&quot;返回 newPath/newName&quot;]
MoveReq[&quot;POST /api/fs/move&quot;] --&gt; CheckSrc[&quot;checkPath(src)&quot;]
CheckSrc --&gt; CheckDest[&quot;checkPath(destDir)&quot;]
CheckDest --&gt; SrcExists[&quot;检查源存在&quot;]
SrcExists --&gt; DestIsDir[&quot;检查目标为目录&quot;]
DestIsDir --&gt; CalcDest[&quot;join(destDir, basename(src))&quot;]
CalcDest --&gt; CheckDestPath[&quot;checkPath(destPath)&quot;]
CheckDestPath --&gt; DestExists{&quot;目标已存在？&quot;}
DestExists --&gt; |是| Conflict409Move[&quot;返回 409 冲突&quot;]
DestExists --&gt; |否| DoMove[&quot;rename(src, destPath)&quot;]
DoMove --&gt; MoveResp[&quot;返回 newPath&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1467-L1512" target="_blank" rel="noreferrer">agent/src/server.js#L1467-L1512</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1514-L1559" target="_blank" rel="noreferrer">agent/src/server.js#L1514-L1559</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1467-L1512" target="_blank" rel="noreferrer">agent/src/server.js#L1467-L1512</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1514-L1559" target="_blank" rel="noreferrer">agent/src/server.js#L1514-L1559</a></li></ul><h3 id="回收站功能-暂存、恢复、清理与持久化" tabindex="-1">回收站功能：暂存、恢复、清理与持久化 <a class="header-anchor" href="#回收站功能-暂存、恢复、清理与持久化" aria-label="Permalink to &quot;回收站功能：暂存、恢复、清理与持久化&quot;">​</a></h3><ul><li><strong>移动至回收站</strong>：<code>moveToTrash</code> 确保回收站目录存在，清理过期条目，统计文件或目录大小，优先使用同文件系统 <code>rename</code>，跨设备时回退为 <code>cp</code> + 删除源，并记录元数据到 <code>metadata.json</code>。</li><li><strong>恢复</strong>：<code>restoreFromTrash</code> 查找条目，检查回收站文件是否存在，检查原位置是否被占用，成功后移回原路径并删除元数据。</li><li><strong>列表</strong>：<code>listTrash</code> 返回有效条目。</li><li><strong>定期清理</strong>：每 6 小时清理超过 7 天的条目，递归删除目录或单个文件，更新元数据。</li><li><strong>语言支持</strong>：通过 <code>setTrashLang</code> 注入请求语言，内部翻译函数优先使用传入的 <code>tFn</code>。</li></ul><pre class="mermaid">flowchart TD
DeleteAPI[&quot;POST /api/fs/delete&quot;] --&gt; CheckPathDel[&quot;checkPath&quot;]
CheckPathDel --&gt; StatDel[&quot;stat 获取 isDir/size&quot;]
StatDel --&gt; MoveTrash[&quot;moveToTrash&quot;]
MoveTrash --&gt; EnsureTrash[&quot;ensureTrashDir&quot;]
EnsureTrash --&gt; CleanExpired[&quot;cleanExpiredTrash&quot;]
CleanExpired --&gt; GetSize[&quot;getDirSize 或 s.size&quot;]
GetSize --&gt; CrossDevice[&quot;movePathCrossDevice&quot;]
CrossDevice --&gt; SaveMeta[&quot;loadMetadata + saveMetadata&quot;]
SaveMeta --&gt; ReturnTrash[&quot;返回 trashId/isDir&quot;]
RestoreAPI[&quot;恢复回收站&quot;] --&gt; LoadMeta[&quot;loadMetadata&quot;]
LoadMeta --&gt; FindEntry[&quot;按 trashId 查找&quot;]
FindEntry --&gt; ExistsTrash{&quot;回收站文件存在？&quot;}
ExistsTrash --&gt; |否| NotFound[&quot;返回 entryNotFound/fileNotFound&quot;]
ExistsTrash --&gt; |是| OriginalOccupied{&quot;原位置被占用？&quot;}
OriginalOccupied --&gt; |是| Occupied[&quot;返回 originalPathOccupied&quot;]
OriginalOccupied --&gt; |否| MoveBack[&quot;movePathCrossDevice 回原路径&quot;]
MoveBack --&gt; RemoveMeta[&quot;删除元数据&quot;]
RemoveMeta --&gt; RestoreOk[&quot;返回 restoredPath&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1145-L1161" target="_blank" rel="noreferrer">agent/src/server.js#L1145-L1161</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L44-L74" target="_blank" rel="noreferrer">agent/src/trash.js#L44-L74</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L100-L158" target="_blank" rel="noreferrer">agent/src/trash.js#L100-L158</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L166-L251" target="_blank" rel="noreferrer">agent/src/trash.js#L166-L251</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L44-L74" target="_blank" rel="noreferrer">agent/src/trash.js#L44-L74</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L100-L158" target="_blank" rel="noreferrer">agent/src/trash.js#L100-L158</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L166-L251" target="_blank" rel="noreferrer">agent/src/trash.js#L166-L251</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1145-L1161" target="_blank" rel="noreferrer">agent/src/server.js#L1145-L1161</a></li></ul><h3 id="文件监控、变更通知、版本管理与冲突解决" tabindex="-1">文件监控、变更通知、版本管理与冲突解决 <a class="header-anchor" href="#文件监控、变更通知、版本管理与冲突解决" aria-label="Permalink to &quot;文件监控、变更通知、版本管理与冲突解决&quot;">​</a></h3><ul><li><strong>文件监控</strong>：Agent 服务器导入 Node <code>watch</code>，但当前文件操作路由中未见基于 <code>watch</code> 的变更事件分发逻辑；现有实现更偏向于按需读取和下载。</li><li><strong>变更通知</strong>：未发现 WebSocket 或轮询机制用于向扩展端推送文件变更事件。</li><li><strong>版本管理</strong>：未发现内置的版本快照、差异比较或 Git 集成；删除走回收站，恢复一次还原。</li><li><strong>冲突解决</strong>：重命名和移动在目标已存在时返回 409；上传同名文件会追加序号；恢复回收站时若原位置被占用则拒绝恢复。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L4-L5" target="_blank" rel="noreferrer">agent/src/server.js#L4-L5</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L790" target="_blank" rel="noreferrer">agent/src/server.js#L751-L790</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1467-L1512" target="_blank" rel="noreferrer">agent/src/server.js#L1467-L1512</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1514-L1559" target="_blank" rel="noreferrer">agent/src/server.js#L1514-L1559</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L210-L240" target="_blank" rel="noreferrer">agent/src/trash.js#L210-L240</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li><code>server.js</code> 依赖 <code>security.js</code> 进行路径校验，依赖 <code>trash.js</code> 处理删除，依赖 <code>logger.js</code> 记录操作，依赖 <code>search.js</code> 提供文件与内容搜索。</li><li><code>security.js</code> 依赖 <code>config.js</code> 获取工作目录和白名单，依赖 <code>i18n.js</code> 提供多语言错误信息。</li><li><code>trash.js</code> 依赖 <code>i18n.js</code> 和 <code>sys-lang.js</code>，并使用 Node <code>fs/promises</code> 完成文件操作。</li><li>扩展端 <code>workspace-manager.js</code> 通过 <code>agentRequest</code> 调用 <code>/api/fs/*</code> 接口。</li></ul><pre class="mermaid">graph LR
Server[&quot;server.js&quot;] --&gt; Security[&quot;security.js&quot;]
Server --&gt; Trash[&quot;trash.js&quot;]
Server --&gt; Logger[&quot;logger.js&quot;]
Server --&gt; Search[&quot;search.js&quot;]
Security --&gt; Config[&quot;config.js&quot;]
Security --&gt; I18n[&quot;i18n.js&quot;]
Trash --&gt; I18n
Trash --&gt; SysLang[&quot;sys-lang.js&quot;]
Workspace[&quot;workspace-manager.js&quot;] --&gt; Server
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L23" target="_blank" rel="noreferrer">agent/src/server.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L6" target="_blank" rel="noreferrer">agent/src/security.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L1-L10" target="_blank" rel="noreferrer">agent/src/trash.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L569-L616" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L569-L616</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L23" target="_blank" rel="noreferrer">agent/src/server.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L6" target="_blank" rel="noreferrer">agent/src/security.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L1-L10" target="_blank" rel="noreferrer">agent/src/trash.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L569-L616" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L569-L616</a></li></ul><h2 id="性能与资源限制" tabindex="-1">性能与资源限制 <a class="header-anchor" href="#性能与资源限制" aria-label="Permalink to &quot;性能与资源限制&quot;">​</a></h2><ul><li><strong>JSON Body 限制</strong>：<code>MAX_BODY_SIZE</code> 为 200MB，防止超大 JSON 请求。</li><li><strong>流式上传限制</strong>：<code>MAX_UPLOAD_SIZE</code> 为 200MB，同时校验 <code>Content-Length</code> 和累计写入字节数，超出即销毁请求和写入流。</li><li><strong>读取大小限制</strong>：<code>read</code>、<code>download</code> 使用 <code>config.fileMaxSize</code> 或默认 50MB，超过直接拒绝。</li><li><strong>流式下载优化</strong>：单文件使用 <code>createReadStream</code> 管道输出；ZIP 打包结果按 64KB 分块写入，配合 <code>setImmediate</code> 让出事件循环，避免阻塞。</li><li><strong>ZIP 打包</strong>：使用 <code>archiver</code> 将目录或路径集合压缩为临时 ZIP，完成后转为 base64 或通过流返回。</li><li><strong>XLSX 预览</strong>：服务端使用 SheetJS 读取前若干行，裁剪空行列，避免前端引入重型库。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L137" target="_blank" rel="noreferrer">agent/src/server.js#L132-L137</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L268-L303" target="_blank" rel="noreferrer">agent/src/server.js#L268-L303</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L305-L383" target="_blank" rel="noreferrer">agent/src/server.js#L305-L383</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L792-L862" target="_blank" rel="noreferrer">agent/src/server.js#L792-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1267-L1385" target="_blank" rel="noreferrer">agent/src/server.js#L1267-L1385</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1387-L1442" target="_blank" rel="noreferrer">agent/src/server.js#L1387-L1442</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li><strong>路径被拒绝</strong>：检查 <code>checkPath</code> 返回的 <code>reason</code>，确认路径是否在 <code>allowedPaths</code> 或工作目录下，且未被硬阻止清单拦截。</li><li><strong>符号链接问题</strong>：如果路径指向符号链接，注意 <code>realpath</code> 会解析到真实路径，真实路径仍需满足白名单。</li><li><strong>删除后找不到文件</strong>：删除操作会返回 <code>trashId</code>，可通过回收站列表和恢复接口找回。</li><li><strong>重命名/移动冲突</strong>：目标已存在时返回 409，需先处理冲突文件或改名。</li><li><strong>上传失败</strong>：检查 <code>Content-Length</code> 是否超过限制，以及脚本文件是否因权限剥离导致无法执行。</li><li><strong>下载过大文件 OOM</strong>：优先使用 <code>/api/fs/download-stream</code>，避免 base64 膨胀和全量内存加载。</li><li><strong>集成测试行为</strong>：读目录、列文件、缺失 path、删除后 stat 等行为有集成测试覆盖，可作为预期行为参考。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1037-L1050" target="_blank" rel="noreferrer">agent/src/server.js#L1037-L1050</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1467-L1512" target="_blank" rel="noreferrer">agent/src/server.js#L1467-L1512</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1514-L1559" target="_blank" rel="noreferrer">agent/src/server.js#L1514-L1559</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/integration/api.integration.test.js#L257-L343" target="_blank" rel="noreferrer">agent/test/integration/api.integration.test.js#L257-L343</a></li></ul><h2 id="安全最佳实践" tabindex="-1">安全最佳实践 <a class="header-anchor" href="#安全最佳实践" aria-label="Permalink to &quot;安全最佳实践&quot;">​</a></h2><ul><li><strong>输入验证</strong>：始终使用 <code>checkPath</code> 校验路径，拒绝空值、相对路径逃逸、不在白名单的路径。</li><li><strong>输出净化</strong>：下载文件名使用 <code>basename</code> 和 URL 编码，避免路径穿越；ZIP 打包只包含合法路径。</li><li><strong>资源限制</strong>：严格限制 JSON body、流式上传、读取和下载大小；脚本文件写入后剥离执行权限。</li><li><strong>审计日志</strong>：所有文件操作通过 <code>logFs</code>、<code>logSecurity</code>、<code>logError</code> 记录路径、大小、类型和错误信息。</li><li><strong>最小权限</strong>：工作目录永远放行，但其他路径必须显式加入 <code>allowedPaths</code>；Agent 系统目录硬阻止。</li><li><strong>防 DoS</strong>：重启、更新、关闭等管理接口有冷却时间和防重入保护。</li><li><strong>跨平台兼容</strong>：路径格式化、大小写、分隔符、盘符处理均考虑 Windows/macOS/Linux 差异。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L443" target="_blank" rel="noreferrer">agent/src/server.js#L417-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L862" target="_blank" rel="noreferrer">agent/src/server.js#L751-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1037-L1559" target="_blank" rel="noreferrer">agent/src/server.js#L1037-L1559</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L100" target="_blank" rel="noreferrer">agent/src/security.js#L62-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>文件操作服务以 <code>server.js</code> 为入口，结合 <code>security.js</code> 的路径白名单与符号链接防护，以及 <code>trash.js</code> 的回收站机制，提供了安全的文件读取、写入、列表、统计、重命名、移动、删除、上传、下载和预览能力。其优势在于：</p><ul><li>多层路径校验与硬阻止清单，防止越权访问。</li><li>回收站软删除与过期清理，降低误删风险。</li><li>流式上传/下载与 ZIP 打包，兼顾大文件与用户体验。</li><li>脚本文件权限剥离与审计日志，提升安全性与可观测性。</li></ul><p>需要注意：</p><ul><li>当前实现没有跨操作的 ACID 事务或自动回滚机制。</li><li>文件监控、变更通知、版本管理并非当前文件操作服务的核心能力。</li><li>批量操作应以“多次原子文件系统调用 + 业务层重试/冲突处理”的方式设计，而非依赖隐式事务。</li></ul>`,88)])])}const b=r(s,[["render",o]]);export{d as __pageData,b as default};
